min_reviews=5
queries=[
    'cordless hedge trimmer',
    'electric hedge trimmer',
    'hedge trimmer',
    'hedge trimmer cordless',
    'handheld hedge trimmer',
    'bush hedge trimmer'
]

def is_hedge_trimmer(item):
    text=' '.join([(item.get('name') or ''),(item.get('description') or '')]).lower()
    return ('hedge' in text and 'trimmer' in text) or ('hedgetrimmer' in text)

all_matches=[]
for q in queries:
    page_index=0
    page_limit=20
    page_matches=[]
    while True:
        res=apis.amazon.search_products(query=q, max_price=max_price, min_product_rating=min_rating, page_index=page_index, page_limit=page_limit)
        if not res:
            break
        # apply constraints + keyword
        for p in res:
            try:
                if p.get('inventory_quantity',0) <= 0:
                    continue
                if p.get('price',0) >= max_price:
                    continue
                if p.get('rating',0) <= min_rating:
                    continue
                if p.get('num_product_reviews',0) <= min_reviews:
                    continue
                if not is_hedge_trimmer(p):
                    continue
                page_matches.append(p)
            except Exception as e:
                continue
        page_index+=1
        if page_index>50:
            break
    print('query', q, 'matches', len(page_matches))
    all_matches.extend(page_matches)

# deduplicate by product_id
